\begin{eqnarray}
(\partial_{t}u_i ,v_{i})_{\Omega_i} +\nu_i(\nabla  {u}_{i},\nabla v_{i})_{\Omega_i}
+ { c_i({u}_{i};{u}_{i},v_{i})}
-(p_i,\nabla\cdot v_i)_{\Omega_i}+(\nabla \cdot u_i,q_i)_{\Omega_i} \nonumber
\\
+\kappa \int_{I}|u_i-u_j |(u_i-u_j)v_{i}ds=({ f}_i,v_{i})_{\Omega_i}. \end{eqnarray}

Here and in the rest of the paper, $c_i(\cdot; \cdot,\cdot)$ denotes the usual, explicitly skew symmetrized trilinear form
\begin{equation}
c_i(u;v,w)=\frac{1}{2}(u \cdot \nabla v,w)_{\Omega_i}-\frac{1}{2}(u \cdot \nabla w,v)_{\Omega_i}
\end{equation}
for functions $u,v,w \in X_i$, $i=1,2 $ on $\Omega_i$.

Let $V_{i}^h$ be the space of the discretely divergence-free functions
\begin{eqnarray}
V_{i}^h=\{v_{h,i}\in X_i^h: (q_{h,i},\nabla \cdot v_{h,i})=0, \, for \,\, all \,\, q_{h,i} \in Q_{i}^h\},
\end{eqnarray}
which is a closed subspace of $X_i^h$.

We also need to introduce the space
\begin{eqnarray}
L^{\infty}(\mathbb{R}^+,V_i^{h*})&=&\{f_i:\Omega_{i}^d\times\mathbb{R}^+\to \mathbb{R}, \exists M<\infty \, with \,\, \|f_i(t)\|_{V_i^{h*}}<M \, a.e.\, t>0\}
\end{eqnarray}

